 IEnumerator routine;readonly Stack<IEnumerator> routines=new Stack<IEnumerator>();bool finished;string folder;readonly List<string> results=new List<string>();Keyboard keyboard;Gamepad pad1,pad2,pad3;InputSettings oldInput,probeInput;HockeyMatch m;
