 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){var args=Environment.GetCommandLineArgs();if(Array.IndexOf(args,"-tsBoardProbe")<0&&Array.IndexOf(args,"-tsSmoke")<0&&Array.IndexOf(args,"-tsBilliardsFeature")<0&&Array.IndexOf(args,"-tsBilliardsRegression")<0)return;var g=new GameObject("Truck Sports opt-in validation");DontDestroyOnLoad(g);g.AddComponent<SportsSmoke>();}
 void Start(){folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../SportsSmokeTest"));Directory.CreateDirectory(folder);oldInput=InputSystem.settings;probeInput=UnityEngine.Object.Instantiate(oldInput);probeInput.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probeInput;Application.logMessageReceived+=Log;SavePrefs();routine=Array.IndexOf(Environment.GetCommandLineArgs(),"-tsBoardProbe")>=0?BoardProbe():Run();routines.Push(routine);}
 void Log(string text,string trace,LogType type){if(!finished&&(type==LogType.Exception||type==LogType.Error))results.Add("RUNTIME ERROR "+text);}
 void Update(){if(finished||routine==null)return;try{while(routines.Count>0){var current=routines.Peek();if(!current.MoveNext()){if(finished)return;routines.Pop();continue;}if(current.Current is IEnumerator nested){routines.Push(nested);continue;}return;}Finish(0);}catch(Exception e){results.Add("FAIL "+e.Message);Debug.LogError("TS_SMOKE_FAIL "+e);Finish(2);}}
 void Check(bool value,string message){if(!value)throw new Exception(message);results.Add("PASS "+message);Debug.Log("TS_SMOKE_PASS "+message);}
 IEnumerator Delay(float seconds){float until=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<until)yield return null;}
 IEnumerator Wait(Func<bool> condition,float seconds,string label){float until=Time.realtimeSinceStartup+seconds;while(!condition()){if(Time.realtimeSinceStartup>until)throw new Exception("Timeout: "+label);yield return null;}}
