 void Restore(){foreach(var p in oldPrefs){if(p.Value==null){PlayerPrefs.DeleteKey(p.Key);continue;}if(p.Key.EndsWith("Master")||p.Key.EndsWith("SFX")||p.Key.EndsWith("Steering"))PlayerPrefs.SetFloat(p.Key,float.Parse(p.Value,System.Globalization.CultureInfo.InvariantCulture));else PlayerPrefs.SetInt(p.Key,int.Parse(p.Value));}PlayerPrefs.Save();}
